1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.Set;
7	
8	import jakarta.validation.Valid;
9	import net.officefloor.plugin.variable.Out;
10	import org.springframework.samples.petclinic.mapper.OwnerMapper;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
14	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
15	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
16	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
17	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
18	import org.springframework.validation.annotation.Validated;
19	import org.springframework.web.bind.annotation.RequestBody;
20	
21	@Validated
22	public class BuildOwner {
23	
24	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
25	            Out<Boolean> sharesHousehold)
26	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
27	            InvalidPostcodeException, FutureRegistrationDateException {
28	        // Publish the request-only 'sharesHousehold' flag for the household duplicate check.
29	        // Not part of the Owner entity, so it travels as a separate variable.
30	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
31	        // Normalize the address fields up front. The structured 'addressLine1'/'addressLine2' are
32	        // preferred over the flat 'address' when supplied; the composed 'address' is the normalized
33	        // 'addressLine1' with the normalized 'addressLine2' appended (single space) when present, and
34	        // falls back to the normalized flat 'address' otherwise. Composing here means the required
35	        // check below rejects an address that is blank in both forms, and every later comparison sees
36	        // the stored normalized form.
37	        request.setAddressLine1(Addresses.normalizeToNull(request.getAddressLine1()));
38	        request.setAddressLine2(Addresses.normalizeToNull(request.getAddressLine2()));
39	        request.setAddress(Addresses.compose(
40	                request.getAddressLine1(), request.getAddressLine2(), request.getAddress()));
41	        List<String> missing = new ArrayList<>();
42	        if (isBlank(request.getFirstName())) {
43	            missing.add("firstName");
44	        }
45	        if (isBlank(request.getLastName())) {
46	            missing.add("lastName");
47	        }
48	        if (isBlank(request.getAddress())) {
49	            missing.add("address");
50	        }
51	        if (isBlank(request.getCity())) {
52	            missing.add("city");
53	        }
54	        if (isBlank(request.getTelephone())) {
55	            missing.add("telephone");
56	        }
57	        if (!missing.isEmpty()) {
58	            throw new MissingOwnerFieldsException(missing);
59	        }
60	        // Normalize the telephone to E.164 form (keep '+'/country code, else assume '+61').
61	        request.setTelephone(Telephones.toE164(request.getTelephone()));
62	        // Email is optional; when present it must be syntactically valid and is stored lower-cased.
63	        request.setEmail(OwnerEmails.normalize(request.getEmail()));
64	        // Postcode is optional; when present it must be valid for the city's region
65	        // (a city with no known region accepts any 4-digit postcode). The 4-digit shape
66	        // is enforced by the request schema, so only the region range is checked here.
67	        Postcodes.validate(request.getCity(), request.getPostcode());
68	        Owner owner = ownerMapper.toOwner(request);
69	        // The effective registration date is the supplied value, or the server's current date when
70	        // none is supplied. Either way it must fall on a business day: a Saturday, Sunday or listed
71	        // public holiday rolls forward to the next non-holiday business day. Everything derived from
72	        // the registration date (membership number year, daily create-limit) then sees this adjusted
73	        // business day.
74	        LocalDate registrationDate = owner.getRegistrationDate();
75	        if (registrationDate == null) {
76	            registrationDate = LocalDate.now();
77	        } else if (registrationDate.isAfter(LocalDate.now())) {
78	            // A supplied registration date may not be in the future.
79	            throw new FutureRegistrationDateException(
80	                    "registrationDate " + registrationDate + " is later than the server date");
81	        }
82	        owner.setRegistrationDate(toBusinessDay(registrationDate));
83	        built.set(owner);
84	    }
85	
86	    /** The fixed public-holiday calendar; a date landing on one of these rolls forward. */
87	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
88	            LocalDate.of(2026, 1, 1),
89	            LocalDate.of(2026, 1, 26),
90	            LocalDate.of(2026, 4, 25),
91	            LocalDate.of(2026, 12, 25),
92	            LocalDate.of(2026, 12, 28));
93	
94	    /**
95	     * Roll a date forward to the next non-holiday business day; a date already on a business day
96	     * (a weekday that is not a listed public holiday) is returned unchanged.
97	     */
98	    private static LocalDate toBusinessDay(LocalDate date) {
99	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
100	            date = date.plusDays(1);
101	        }
102	        return date;
103	    }
104	
105	    private static boolean isWeekend(LocalDate date) {
106	        return switch (date.getDayOfWeek()) {
107	            case SATURDAY, SUNDAY -> true;
108	            default -> false;
109	        };
110	    }
111	
112	    private static boolean isBlank(String value) {
113	        return value == null || value.isBlank();
114	    }
115	}
