1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Emits an audit line to the dedicated {@code AUDIT} logger once the owner has been
11	 * persisted, recording the assigned id, the {@code customerCode}, the
12	 * {@code registrationDate}, the {@code membershipPoints}, the {@code membershipLevel}
13	 * and the {@code membershipNumber}.
14	 */
15	public class AuditOwnerCreated {
16	
17	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        int points = Memberships.membershipPoints(owner, Households.size(owner, ownerRepository));
21	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipPoints={} "
22	                + "membershipLevel={} membershipNumber={}",
23	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
24	                points, Memberships.membershipLevel(points), membershipNumber(owner));
25	    }
26	
27	    /**
28	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of the
29	     * fiscal year (starting 1 July) containing the registrationDate (e.g. 'NSW-1A2B3C4D-M27').
30	     * Returns {@code null} when either the customer code or the registration date is absent (e.g.
31	     * legacy seed owners). Mirrors the {@code membershipNumber} exposed on the owner response.
32	     */
33	    private static String membershipNumber(Owner owner) {
34	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
35	            return null;
36	        }
37	        return String.format("%s-M%02d", owner.getCustomerCode(),
38	                FiscalYears.of(owner.getRegistrationDate()) % 100);
39	    }
40	}
