1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
9	
10	/**
11	 * Rejects creating an owner when 100 or more owners already share this owner's registration date,
12	 * counted by {@link Owner#getRegistrationDate()}. That date is the adjusted business day, so the
13	 * cap is enforced per business day. The owner being created is not yet persisted, so it is not part
14	 * of the count.
15	 */
16	public class EnsureDailyOwnerLimit {
17	
18	    private static final int MAX_OWNERS_PER_DAY = 100;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
21	            throws DailyOwnerLimitException {
22	        LocalDate registrationDate = owner.getRegistrationDate();
23	        long count = ownerRepository.findAll().stream()
24	                .filter(existing -> !existing.getId().equals(owner.getId()))
25	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
26	                .count();
27	        if (count >= MAX_OWNERS_PER_DAY) {
28	            throw new DailyOwnerLimitException(
29	                    MAX_OWNERS_PER_DAY + " or more owners have already been created for "
30	                            + registrationDate);
31	        }
32	    }
33	}
