6	/**
7	 * Assigns the owner's deterministic {@code householdId} (see {@link Households}): the first 12 hex
8	 * characters of {@code SHA-256(normalizedLastName + '|' + postcode)}.
9	 *
10	 * <p>The id is derived from the last name and postcode alone, so every owner at the same last name
11	 * and postcode resolves to the same value automatically. It is assigned unconditionally — the
12	 * request's {@code sharesHousehold} flag no longer creates the link, it only bypasses the household
13	 * duplicate block in {@link EnsureUniqueIdentity}.
14	 */
15	public class AssignHousehold {
16	
17	    public void service(@Val Owner owner) {
18	        owner.setHouseholdId(Households.id(owner));
19	    }
20	}
