1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * The household duplicate block. Because the household is keyed on (last name, postcode) through the
10	 * deterministic {@link Households#id(Owner) householdId}, a second owner in a household that already
11	 * has a member is a duplicate and is rejected (409).
12	 *
13	 * <p>The request's {@code sharesHousehold} flag bypasses this block: a declared household member is
14	 * created even though its household already exists. Runs after {@link AssignHousehold} so the new
15	 * owner's {@code householdId} is set; existing owners are compared by their own computed household.
16	 */
17	public class EnsureUniqueIdentity {
18	
19	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
20	            throws DuplicateIdentityException {
21	        if (Boolean.TRUE.equals(sharesHousehold)) {
22	            return; // declared household member: allowed to join an existing household
23	        }
24	        String householdId = owner.getHouseholdId();
25	        boolean inUse = ownerRepository.findAll().stream()
26	                .filter(existing -> !existing.getId().equals(owner.getId()))
27	                .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted())) // ignore soft-deleted owners
28	                .anyMatch(existing -> householdId.equals(Households.id(existing)));
29	        if (inUse) {
30	            throw new DuplicateIdentityException(
31	                    "An owner in household " + householdId + " already exists");
32	        }
33	    }
34	}
